      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "आत्मारामः फलाशी गुरुवचनरतस्त्वत्प्रसादात्स्मरारे",
          "end": "line"
        },
        {
          "n": 2,
          "text": "दुःखान्मोक्ष्ये कदाहं तव चरणरतो ध्यानमार्गैकप्रश्नः ॥ ९३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "",
          "end": "line"
        },
        {
          "n": 2,
          "text": "शय्या शैलशिला गृहं गिरिगुहा वस्त्रं तरूणां त्वचः",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "line"
        },
        {
          "n": 4,
          "text": "",
          "end": "line"
        },
        {
          "n": 5,
          "text": "सारङ्गाः सुहृदो ननु क्षितिरुहां वृत्तिः फलैः कोमलैः ।",
          "end": "line"
        },
        {
          "n": 6,
          "text": "",
          "end": "line"
        },
        {
          "n": 7,
          "text": "",
          "end": "line"
        },
        {
          "n": 8,
          "text": "येषां निर्झरमम्बुपानमुचितं रत्येव विद्याङ्गना",
          "end": "line"
        },
        {
          "n": 9,
          "text": "मन्ये ते परमेश्वराः शिरसि यैर्बद्धो न सेवाञ्जलिः ॥ ९४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "सत्यामेव त्रिलोकीसरिति हरशिरश्चुम्बिनीविच्छटायां",
          "end": "line"
        },
        {
          "n": 2,
          "text": "सद्वृत्तिं कल्पयन्त्यां वटविटपभवैर्वल्कलैः सत्फलैश्च ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "कोयं विद्वान्विपत्तिज्वरजनितरुजातीव दुःखासिकानां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "वक्त्रं वीक्षेत दुःस्थे यदि हि न बिभृयात्स्वे कुटुम्बेनुकम्पाम् ॥९५॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "उद्यानेषु विचित्रभोजनविधिस्तीव्रातितीव्रं तपः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "कौपीनावरणं सुवस्त्रममितं भिक्षाटनं मण्डनम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "आसन्नं मरणं च मङ्गलसमं यस्यां समुत्पद्यते",
          "end": "line"
        },
        {
          "n": 4,
          "text": "तां काशीं परिहृत्य हन्त विबुधैरन्यत्र किं स्थीयते ॥ ९६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "नायं ते समयो रहस्यमधुना निद्राति नाथो यदि",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्थित्वा द्रक्ष्यति कुप्यति प्रभुरिति द्वारिषु येषां वचः ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
